typedef void    (* Exec_Func) (void *) ;

typedef void *		Exec_Arg           ;

typedef struct s_Exec_Q_Msg
{
	Q_Msg     q_base ; 	// MUST BE FIRST ELEMENT OF THE STRUCT

	Exec_Arg  cmd    ;  // order is important
	Exec_Arg  arg    ;
	
	
	Exec_Func func   ;
	
} Exec_Q_Msg ;

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

void         exec_init          (const UInt8 task_num) ;

void 		 exec_q_insert 		(Exec_Q_Msg * exec_q_msg, Exec_Func exec_func , ...);

Exec_Q_Msg * exec_q_remove      (Q exec_q_free) ;

Q            exec_q_free_create (const UInt8 exec_q_free_size) ;

Boolean		 exec_q_free_add	( Q q_free , UInt8 size_of_message );

